  'Apply evenly around the plant root zone during active vegetative growth; protects against soil nematodes and grubs.': {
    hi: 'सक्रिय वानस्पतिक वृद्धि के दौरान पौधों की जड़ों के पास समान रूप से डालें; यह मिट्टी के सूत्रकृमि और सफेद लट से बचाता है।',
    mr: 'पीक वाढीच्या टप्प्यात मुळांभोवती समप्रमाणात टाका; यामुळे हुमणी आणि सूत्रकृमींपासून संरक्षण मिळते.',
    gu: 'સક્રિય વૃદ્ધિ દરમિયાન છોડના મૂળની આસપાસ સરખી રીતે નાખો; તે જમીનના કૃમિ અને ઇયળથી રક્ષણ આપે છે.',
    pa: 'ਵਧਣ ਦੇ ਸਮੇਂ ਦੌਰਾਨ ਪੌਦਿਆਂ ਦੀਆਂ ਜੜ੍ਹਾਂ ਦੇ ਆਲੇ-ਦੁਆਲੇ ਬਰਾਬਰ ਪਾਓ; ਇਹ ਮਿੱਟੀ ਦੇ ਕੀੜਿਆਂ ਤੋਂ ਬਚਾਉਂਦਾ ਹੈ।',
    ta: 'பயிர் வளர்ச்சி நிலையில் வேர்களைச் சுற்றி சமமாக இடவும்; இது நூற்புழு மற்றும் வேர்ப்புழுக்களில் இருந்து பாதுகாக்கிறது.',
    te: 'మొక్క ఎదుగుదల దశలో వేర్ల చుట్టూ సమానంగా వేయండి; ఇది నేల నులిపురుగులు మరియు వేరు పురుగుల నుండి రక్షిస్తుంది.',
  },
