  'Dust evenly around plants during flowering/fruiting to boost sweetness, grain weight, and stem strength.': {
    hi: 'फूल आने और फल बनने के दौरान पौधों के चारों ओर समान रूप से छिड़कें; इससे दाने का वजन और तने की मजबूती बढ़ती है।',
    mr: 'फुलोरा व फळधारणेच्या काळात पिकांभोवती समप्रमाणात टाका; यामुळे दाण्यांचे वजन आणि खोडाची ताकद वाढते.',
    gu: 'ફૂલ અને ફળ આવતી વખતે છોડની આસપાસ સરખી રીતે છાંટો; તેનાથી દાણાનું વજન અને થડની મજબૂતાઈ વધે છે.',
    pa: 'ਫੁੱਲ ਅਤੇ ਫਲ ਲੱਗਣ ਵੇਲੇ ਪੌਦਿਆਂ ਦੇ ਆਲੇ-ਦੁਆਲੇ ਬਰਾਬਰ ਛਿੜਕੋ; ਇਸ ਨਾਲ ਦਾਣਿਆਂ ਦਾ ਭਾਰ ਅਤੇ ਤਣੇ ਦੀ ਮਜ਼ਬੂਤੀ ਵਧਦੀ ਹੈ।',
    ta: 'பூ மற்றும் காய் பிடிக்கும் தருணத்தில் செடிகளைச் சுற்றித் தூவவும்; இது தானிய எடையையும் தண்டு வலுவையும் அதிகரிக்கும்.',
    te: 'పూత మరియు కాయ దశలో మొక్కల చుట్టూ సమానంగా చల్లండి; ఇది గింజ బరువు మరియు కాండం బలాన్ని పెంచుతుంది.',
  },
