  'Place 5 cm below seeds during sowing or mix into root zone tillage. Phosphorus acts slowly and needs early availability.': {
    hi: 'बुवाई के समय बीज से 5 सेमी नीचे डालें या जड़ क्षेत्र में मिलाएं। फॉस्फोरस धीरे असर करता है इसलिए शुरुआत में जरूरी है।',
    mr: 'पेरणीच्या वेळी बियाण्याखाली ५ सेमी खोलीवर द्या किंवा मुळांच्या कक्षेत मिसळा. स्फुरद हळू कार्य करते म्हणून सुरुवातीला आवश्यक असते.',
    gu: 'વાવણી વખતે બીજથી 5 સેમી નીચે મૂકો અથવા મૂળ વિસ્તારમાં ભેળવો. ફોસ્ફરસ ધીમે અસર કરે છે તેથી વહેલી ઉપલબ્ધતા જરૂરી છે.',
    pa: 'ਬਿਜਾਈ ਵੇਲੇ ਬੀਜ ਤੋਂ 5 ਸੈਂਟੀਮੀਟਰ ਹੇਠਾਂ ਪਾਓ ਜਾਂ ਜੜ੍ਹਾਂ ਵਾਲੀ ਮਿੱਟੀ ਵਿੱਚ ਮਿਲਾਓ। ਫਾਸਫੋਰਸ ਹੌਲੀ ਕੰਮ ਕਰਦਾ ਹੈ।',
    ta: 'விதைக்கும் போது விதைக்கு 5 செ.மீ கீழே இடவும் அல்லது வேர் பகுதியில் கலக்கவும். பாஸ்பரஸ் மெதுவாகச் செயல்படும்.',
    te: 'విత్తేటప్పుడు విత్తనానికి 5 సెం.మీ లోతులో వేయండి లేదా వేరు ప్రాంతంలో కలపండి. భాస్వరం నెమ్మదిగా పనిచేస్తుంది.',
  },
