    mr: 'पीक शिफारस प्रणाली',
    gu: 'પાક ભલામણ સિસ્ટમ',
    pa: 'ਫ਼ਸਲ ਸਿਫ਼ਾਰਸ਼ ਪ੍ਰਣਾਲੀ',
    ta: 'பயிர் பரிந்துரை அமைப்பு',
