    pa: 'ਘੱਟ ਪ੍ਰੀਮੀਅਮ ਤੇ ਫ਼ਸਲ ਦੇ ਨੁਕਸਾਨ ਦਾ ਪੂਰਾ ਮੁਆਵਜ਼ਾ',
